{
  "目的": "指定されたネコの年間費用を計算し、合計金額を出力する",
  "入力データ": {
    "エサ代": 5000,
    "トイレ砂": 1000,
    "保険": 20000,
    "健康診断": 5000
  }

{
  "目的": "指定された画像URLから画像を読み込み、指定された座標に描画し、画像の一部分を切り出して、指定された座標に描画する",
  "入力データ": {
    "画像URL": "指定された画像URL",
    "座標": {"x":指定されたx座標, "y":指定されたy座標},
    "切り出す部分": {"x":指定されたx座標, "y":指定されたy座標, "width":指定された幅, "height":指定された高さ}
  }
